1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"net/http"
8		"strings"
9	
10		"github.com/entireio/cli/internal/coreapi"
11	)
12	
13	// Control-plane commands reference orgs and projects by their parent ULID in
14	// many places (repo create --project, project create --owner, grant org/project
15	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
16	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
17	// turn a name into its ULID. A ULID is always passed straight through with no
18	// network call. A name is resolved by the control plane's O(1), case-insensitive
19	// by-name lookup (the server matches on lower(name) and returns the single match
20	// under the response's singular `org`/`project` field, or 404) — the CLI never
21	// lists everything and filters client-side.
22	
23	// providerGitHub is the identity-provider slug for GitHub-backed accounts, the
24	// provider half of a qualified grantee handle like "github:alice". GitHub is the
25	// only provider with backing accounts today; other slugs resolve once they exist
26	// server-side.
27	//
28	// Three unrelated concerns spell GitHub the same way, and each keeps its own
29	// constant so a rename upstream moves one of them rather than all three: this
30	// one (which account provider backs a grantee), repoProviderGitHub below (which
31	// forge backs a repository), and setup.go's checkpointProviderGitHub (which
32	// service hosts a repo's checkpoints).
33	const providerGitHub = "github"
34	
35	// repoProviderGitHub and repoProviderEntire are the values of a repository's
36	// `provider` field; the wire enum is "github" | "entire". They answer "which
37	// forge backs this repo", which is a different question from providerGitHub's
38	// "which provider backs this account" — see the note there.
39	//
40	// The field is optional and open on the client (normalize.go drops it from
41	// `required` and strips its enum), so a caller must test for the value it
42	// wants and treat everything else as unknown rather than as the other one.
43	const (
44		repoProviderGitHub = "github"
45		repoProviderEntire = "entire"
46	)
47	
48	// projectRefClient and repoRefClient are the narrow control-plane surfaces the
49	// name resolvers need. Keeping the helpers on interfaces lets repo-scoped
50	// callers resolve a native /et/<project>/<repo> identity with the same client
51	// they use to locate its home cell.
52	type projectRefClient interface {
53		ListProjects(ctx context.Context, params coreapi.ListProjectsParams) (*coreapi.ListProjectsOutputBody, error)
54	}
55	
56	type repoRefClient interface {
57		projectRefClient
58		ListProjectRepos(ctx context.Context, params coreapi.ListProjectReposParams) (*coreapi.ListProjectReposOutputBody, error)
59	}
60	
61	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
62	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
63	// The check is shape-only and case-insensitive on the alphabet; it never hits
64	// the network. A name that happened to be 26 valid base32 characters would be
65	// misread as an id, but real org/project names don't take that form, and the
66	// user can always fall back to the explicit ULID.
67	func looksLikeULID(s string) bool {
68		if len(s) != 26 {
69			return false
70		}
71		for _, r := range strings.ToUpper(s) {
72			switch {
73			case r >= '0' && r <= '9':
74			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
75			default:
76				return false
77			}
78		}
79		return true
80	}
81	
82	// isCoreNotFound reports whether err is a control-plane 404. The by-name lookups
83	// (ListOrgs/ListProjects/ListOrgProjects with ?name=) return 404 when nothing
84	// matches; callers turn that into a friendly "no X named" message.
85	func isCoreNotFound(err error) bool {
86		var se *coreapi.ErrorModelStatusCode
87		return errors.As(err, &se) && se.StatusCode == http.StatusNotFound
88	}
89	
90	// resolveOrgRef turns an org reference (ULID or name) into its ULID. A ULID is
91	// returned unchanged; a name is resolved via the server's case-insensitive
92	// by-name lookup.
93	func resolveOrgRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
94		if looksLikeULID(ref) {
95			return ref, nil
96		}
97		out, err := c.ListOrgs(ctx, coreapi.ListOrgsParams{Name: coreapi.NewOptString(ref)})
98		if err != nil {
99			if isCoreNotFound(err) {
100				return "", noOrgNamedErr(ref)
101			}
102			return "", err
103		}
104		org, ok := out.Response.Org.Get()
105		if !ok {
106			return "", noOrgNamedErr(ref)
107		}
108		return org.ID, nil
109	}
110	
111	// resolveAccountRef turns an account reference into its ULID. A ULID passes
112	// through unchanged; otherwise the ref is a provider-qualified handle (e.g.
113	// "github:alice") resolved via the control plane. We support github-backed
114	// user accounts today; other providers will resolve once they exist server-side.
115	func resolveAccountRef(ctx context.Context, c *coreapi.Client, ref string) (string, error) {
116		if looksLikeULID(ref) {
117			return ref, nil
118		}
119		provider, handle, err := parseQualifiedHandle(ref)
120		if err != nil {
121			return "", err
122		}
123		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: provider, Handle: handle})
124		if err != nil {
125			return "", err
126		}
127		// ResolvedIdentity.AccountId is a plain string, so a handle that resolves to
128		// an identity with no backing account would silently forward "" as the owner
129		// ULID and fail later with an opaque server-side create error. Catch it here.
130		if id.AccountId == "" {
131			return "", fmt.Errorf("handle %q resolved to no account", ref)
132		}
133		return id.AccountId, nil
134	}
135	
136	// resolveGranteeProvider turns a grantee reference into the (provider,
137	// providerUserId) pair the grant/membership "by provider" routes key on. The
138	// reference is a provider-qualified handle (e.g. "github:alice"); it is
139	// resolved through the control plane to the provider's stable numeric user id.
140	// The friendly handle alone is not what the grant routes accept — passing it as
141	// --provider-user-id was the COR-699 footgun ("provider identity not found") —
142	// so the CLI always resolves it first. A bare account ULID is rejected here:
143	// the by-provider routes can't be addressed by ULID, and there is no reverse
144	// account→provider-id lookup; callers that accept a ULID grantee (project/repo
145	// remove) handle it via the typed-id route before reaching this helper.
146	func resolveGranteeProvider(ctx context.Context, c *coreapi.Client, ref string) (provider, providerUserID string, err error) {
147		// A ULID is a tempting paste from `grant … list` (which prints the grantee
148		// ID), but the by-provider routes can't be addressed by ULID. Reject it with
149		// a message that points at the form this command actually wants, rather than
150		// letting parseQualifiedHandle dangle a "(or a ULID)" hint that doesn't apply.
151		if looksLikeULID(ref) {
152			return "", "", fmt.Errorf("grantee %q is an account ULID; this command needs a provider-qualified handle like \"github:alice\"", ref)
153		}
154		p, handle, err := parseQualifiedHandle(ref)
155		if err != nil {
156			return "", "", err
157		}
158		id, err := c.ResolveHandle(ctx, coreapi.ResolveHandleParams{Provider: p, Handle: handle})
159		if err != nil {
160			if isCoreNotFound(err) {
161				return "", "", fmt.Errorf("no %s identity for handle %q", p, handle)
162			}
163			return "", "", err
164		}
165		if id.ProviderUserId == "" {
166			return "", "", fmt.Errorf("handle %q resolved to no provider user id", ref)
167		}
168		// Prefer the server-normalized provider over the raw prefix, falling back to
169		// the input when the response omits it.
170		if id.Provider != "" {
171			p = id.Provider
172		}
173		return p, id.ProviderUserId, nil
174	}
175	
176	// parseQualifiedHandle splits a provider-qualified handle like "github:alice"
177	// into its provider ("github") and handle ("alice"). Accounts are addressed by
178	// this friendly form; a value with no "provider:" prefix is rejected so the
179	// user gets a clear hint rather than a confusing lookup miss.
180	func parseQualifiedHandle(ref string) (provider, handle string, err error) {
181		provider, handle, ok := strings.Cut(ref, ":")
182		if !ok || provider == "" || handle == "" {
183			return "", "", fmt.Errorf("account %q must be a qualified handle like \"github:alice\" (or a ULID)", ref)
184		}
185		return provider, handle, nil
186	}
187	
188	// resolveProjectRef turns a project reference (ULID or name) into its ULID. A
189	// ULID is returned unchanged; a name is resolved via the server's
190	// case-insensitive by-name lookup (the same call `entire project list --name`
191	// uses). Project names are globally unique, so a name maps to at most one project.
192	func resolveProjectRef(ctx context.Context, c projectRefClient, ref string) (string, error) {
193		if looksLikeULID(ref) {
194			return ref, nil
195		}
196		out, err := c.ListProjects(ctx, coreapi.ListProjectsParams{Name: coreapi.NewOptString(ref)})
197		if err != nil {
198			if isCoreNotFound(err) {
199				return "", noProjectNamedErr(ref)
200			}
201			return "", fmt.Errorf("list projects: %w", err)
202		}
203		project, ok := out.Project.Get()
204		if !ok {
205			return "", noProjectNamedErr(ref)
206		}
207		return project.ID, nil
208	}
209	
210	// resolveRepoRef turns a repo reference into its ULID. A ULID passes through.
211	// A name requires a project scope (projectRef, itself a name or ULID) because
212	// repo names are unique only within a project: the repo is resolved via the
213	// server's case-insensitive by-name lookup, scoped to that project. Like the
214	// org/project endpoints, a name-filtered list returns the single match under the
215	// response's singular `repo` field (the plural `repos` is only populated for an
216	// unfiltered page) — reading `repos` here was the COR-699 bug.
217	func resolveRepoRef(ctx context.Context, c repoRefClient, ref, projectRef string) (string, error) {
218		if looksLikeULID(ref) {
219			return ref, nil
220		}
221		if projectRef == "" {
222			return "", fmt.Errorf("repo %q is a name; pass --project <name|ULID> to resolve it, or use a repo ULID", ref)
223		}
224		projID, err := resolveProjectRef(ctx, c, projectRef)
225		if err != nil {
226			return "", err
227		}
228		out, err := c.ListProjectRepos(ctx, coreapi.ListProjectReposParams{ProjectId: projID, Name: coreapi.NewOptString(ref)})
229		if err != nil {
230			if isCoreNotFound(err) {
231				return "", noRepoNamedErr(ref)
232			}
233			return "", fmt.Errorf("list project repos: %w", err)
234		}
235		repo, ok := out.Repo.Get()
236		if !ok {
237			return "", noRepoNamedErr(ref)
238		}
239		return repo.ID, nil
240	}
241	
242	func noOrgNamedErr(name string) error {
243		return fmt.Errorf("no org named %q (run `entire org list` to see names, or pass a ULID)", name)
244	}
245	
246	var errNamedRefNotFound = errors.New("named reference not found")
247	
248	// namedRefNotFoundError preserves the actionable user-facing message while
249	// allowing repository-routing callers to classify a definitive lookup miss.
250	type namedRefNotFoundError struct{ message string }
251	
252	func (e *namedRefNotFoundError) Error() string { return e.message }
253	func (e *namedRefNotFoundError) Unwrap() error { return errNamedRefNotFound }
254	
255	func noProjectNamedErr(name string) error {
256		return &namedRefNotFoundError{message: fmt.Sprintf("no project named %q (run `entire project list` to see names, or pass a ULID)", name)}
257	}
258	
259	func noRepoNamedErr(name string) error {
260		return &namedRefNotFoundError{message: fmt.Sprintf("no repo named %q in that project (run `entire repo list <project>` to see names, or pass a ULID)", name)}
261	}
262	
263	// resolvedRefLabel formats a reference for a success message so it always
264	// names the resolved ULID. When the user passed a ULID (ref == id) it returns
265	// the id alone; when they passed a name it returns "name (id)" so the message
266	// is unambiguous in environments where names can be reused across orgs/projects.
267	func resolvedRefLabel(ref, id string) string {
268		if ref == id {
269			return id
270		}
271		return fmt.Sprintf("%s (%s)", ref, id)
272	}
273	
274	// toProjectList adapts a name-filtered project response — which returns the
275	// single match under the response's singular `project` field — into a slice for
276	// list output (empty when the field is unset).
277	func toProjectList(p coreapi.OptProject) []coreapi.Project {
278		if v, ok := p.Get(); ok {
279			return []coreapi.Project{v}
