1	package cli
2	
3	import (
4		"context"
5		"fmt"
6		"net/http"
7		"net/http/httptest"
8		"strings"
9		"sync/atomic"
10		"testing"
11	
12		"github.com/entireio/cli/internal/coreapi"
13	)
14	
15	// Valid ULID-shaped fixtures (26 Crockford base32 chars, no I/L/O/U) so the
16	// resolver tests exercise the ULID short-circuit instead of a name lookup.
17	const (
18		ulidOrgAcme        = "REDACTED"
19		ulidOrgGlobex      = "REDACTED"
20		ulidProjectWidgets = "REDACTED"
21		ulidAccount        = "REDACTED"
22		ulidResolvedAcct   = "REDACTED"
23	)
24	
25	// resolveTestClient builds a coreapi client pointed at a test server whose
26	// handler is h, and returns the client plus a counter of HTTP requests seen.
27	// It lets the resolver tests assert the load-bearing invariant from
28	// resolveref.go's doc comment: a ULID ref makes zero network calls, a name ref
29	// makes exactly one.
30	func resolveTestClient(t *testing.T, h http.HandlerFunc) (*coreapi.Client, *atomic.Int64) {
31		t.Helper()
32		var calls atomic.Int64
33		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
34			calls.Add(1)
35			w.Header().Set("Content-Type", "application/json")
36			h(w, r)
37		}))
38		t.Cleanup(srv.Close)
39		c, err := coreapi.NewWithBearer(srv.URL, "tok")
40		if err != nil {
41			t.Fatalf("NewWithBearer: %v", err)
42		}
43		return c, &calls
44	}
45	
46	func TestResolveOrgRef(t *testing.T) {
47		t.Parallel()
48	
49		t.Run("ULID passes through without a network call", func(t *testing.T) {
50			t.Parallel()
51			c, calls := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
52				t.Error("unexpected HTTP call for a ULID ref")
53				w.WriteHeader(http.StatusInternalServerError)
54			})
55			got, err := resolveOrgRef(context.Background(), c, ulidOrgGlobex)
56			if err != nil {
57				t.Fatalf("resolveOrgRef: %v", err)
58			}
59			if got != ulidOrgGlobex {
60				t.Errorf("resolveOrgRef = %q, want the ULID unchanged", got)
61			}
62			if n := calls.Load(); n != 0 {
63				t.Errorf("ULID ref made %d HTTP calls, want 0", n)
64			}
65		})
66	
67		t.Run("name is resolved server-side in one call", func(t *testing.T) {
68			t.Parallel()
69			var gotName string
70			c, calls := resolveTestClient(t, func(w http.ResponseWriter, r *http.Request) {
71				gotName = r.URL.Query().Get("name")
72				if err := printJSON(w, &coreapi.ListOrgsOutputBody{Org: coreapi.NewOptOrg(coreapi.Org{ID: ulidOrgGlobex, Name: "globex"})}); err != nil {
73					t.Errorf("encode org: %v", err)
74				}
75			})
76			got, err := resolveOrgRef(context.Background(), c, "globex")
77			if err != nil {
78				t.Fatalf("resolveOrgRef: %v", err)
79			}
80			if got != ulidOrgGlobex {
81				t.Errorf("resolveOrgRef = %q, want globex id", got)
82			}
83			if gotName != "globex" {
84				t.Errorf("server received name=%q, want %q (filtering must be server-side)", gotName, "globex")
85			}
86			if n := calls.Load(); n != 1 {
87				t.Errorf("name ref made %d HTTP calls, want 1", n)
88			}
89		})
90	
91		t.Run("unknown name is a friendly error", func(t *testing.T) {
92			t.Parallel()
93			c, _ := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
94				if err := printJSON(w, &coreapi.ListOrgsOutputBody{}); err != nil {
95					t.Errorf("encode empty: %v", err)
96				}
97			})
98			_, err := resolveOrgRef(context.Background(), c, "nope")
99			if err == nil || !strings.Contains(err.Error(), "no org named") {
100				t.Errorf("resolveOrgRef unknown name: err = %v, want a \"no org named\" error", err)
101			}
102		})
103	}
104	
105	func TestResolveProjectRef(t *testing.T) {
106		t.Parallel()
107		matched := coreapi.NewOptProject(coreapi.Project{ID: ulidProjectWidgets, Name: "widgets", OwnerId: ulidOrgAcme, OwnerType: coreapi.ProjectOwnerTypeOrg})
108	
109		t.Run("ULID passes through without a network call", func(t *testing.T) {
110			t.Parallel()
111			c, calls := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
112				t.Error("unexpected HTTP call for a ULID ref")
113				w.WriteHeader(http.StatusInternalServerError)
114			})
115			got, err := resolveProjectRef(context.Background(), c, ulidProjectWidgets)
116			if err != nil {
117				t.Fatalf("resolveProjectRef: %v", err)
118			}
119			if got != ulidProjectWidgets {
120				t.Errorf("resolveProjectRef = %q, want the ULID unchanged", got)
121			}
122			if n := calls.Load(); n != 0 {
123				t.Errorf("ULID ref made %d HTTP calls, want 0", n)
124			}
125		})
126	
127		t.Run("name is resolved server-side in one call", func(t *testing.T) {
128			t.Parallel()
129			var gotName string
130			c, calls := resolveTestClient(t, func(w http.ResponseWriter, r *http.Request) {
131				gotName = r.URL.Query().Get("name")
132				if err := printJSON(w, &coreapi.ListProjectsOutputBody{Project: matched}); err != nil {
133					t.Errorf("encode project: %v", err)
134				}
135			})
136			got, err := resolveProjectRef(context.Background(), c, "widgets")
137			if err != nil {
138				t.Fatalf("resolveProjectRef: %v", err)
139			}
140			if got != ulidProjectWidgets {
141				t.Errorf("resolveProjectRef = %q, want widgets id", got)
142			}
143			if gotName != "widgets" {
144				t.Errorf("server received name=%q, want %q (filtering must be server-side)", gotName, "widgets")
145			}
146			if n := calls.Load(); n != 1 {
147				t.Errorf("name ref made %d HTTP calls, want 1", n)
148			}
149		})
150	
151		t.Run("unknown name is a friendly error", func(t *testing.T) {
152			t.Parallel()
153			c, _ := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
154				if err := printJSON(w, &coreapi.ListProjectsOutputBody{}); err != nil {
155					t.Errorf("encode empty: %v", err)
156				}
157			})
158			_, err := resolveProjectRef(context.Background(), c, "nope")
159			if err == nil || !strings.Contains(err.Error(), "no project named") {
160				t.Errorf("resolveProjectRef unknown name: err = %v, want a \"no project named\" error", err)
161			}
162		})
163	}
