165	func TestResolveRepoRef(t *testing.T) {
166		t.Parallel()
167		const ulidRepoWeb = "REDACTED"
168	
169		t.Run("ULID passes through without a network call", func(t *testing.T) {
170			t.Parallel()
171			c, calls := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
172				t.Error("unexpected HTTP call for a ULID ref")
173				w.WriteHeader(http.StatusInternalServerError)
174			})
175			got, err := resolveRepoRef(context.Background(), c, ulidRepoWeb, "")
176			if err != nil {
177				t.Fatalf("resolveRepoRef: %v", err)
178			}
179			if got != ulidRepoWeb {
180				t.Errorf("resolveRepoRef = %q, want the ULID unchanged", got)
181			}
182			if n := calls.Load(); n != 0 {
183				t.Errorf("ULID ref made %d HTTP calls, want 0", n)
184			}
185		})
186	
187		t.Run("name without --project is rejected before any call", func(t *testing.T) {
188			t.Parallel()
189			c, calls := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
190				t.Error("unexpected HTTP call when project scope is missing")
191				w.WriteHeader(http.StatusInternalServerError)
192			})
193			_, err := resolveRepoRef(context.Background(), c, "web", "")
194			if err == nil || !strings.Contains(err.Error(), "pass --project") {
195				t.Errorf("resolveRepoRef without project: err = %v, want a \"pass --project\" error", err)
196			}
197			if n := calls.Load(); n != 0 {
198				t.Errorf("missing-scope made %d HTTP calls, want 0", n)
199			}
200		})
201	
202		t.Run("name is resolved server-side, scoped to the project", func(t *testing.T) {
203			t.Parallel()
204			var gotName string
205			c, calls := resolveTestClient(t, func(w http.ResponseWriter, r *http.Request) {
206				gotName = r.URL.Query().Get("name")
207				// A name-filtered list returns the single match under the singular
208				// `repo` field (like org/project) — NOT the plural `repos` array,
209				// which is only populated for an unfiltered page. Reading `repos`
210				// here was the COR-699 bug, so the fixture must mirror the real
211				// server's singular field to keep that regression covered.
212				if err := printJSON(w, &coreapi.ListProjectReposOutputBody{Repo: coreapi.NewOptRepo(coreapi.Repo{ID: ulidRepoWeb, Name: "web"})}); err != nil {
213					t.Errorf("encode repo: %v", err)
214				}
215			})
216			// Project passed as a ULID so resolveProjectRef short-circuits (no call);
217			// only the repo by-name lookup hits the server — one O(1) call.
218			got, err := resolveRepoRef(context.Background(), c, "web", ulidProjectWidgets)
219			if err != nil {
220				t.Fatalf("resolveRepoRef: %v", err)
221			}
222			if got != ulidRepoWeb {
223				t.Errorf("resolveRepoRef = %q, want web id", got)
224			}
225			if gotName != "web" {
226				t.Errorf("server received name=%q, want %q (filtering must be server-side)", gotName, "web")
227			}
228			if n := calls.Load(); n != 1 {
229				t.Errorf("name ref made %d HTTP calls, want 1", n)
230			}
231		})
232	
233		t.Run("unknown name is a friendly error", func(t *testing.T) {
234			t.Parallel()
235			c, _ := resolveTestClient(t, func(w http.ResponseWriter, _ *http.Request) {
236				if err := printJSON(w, &coreapi.ListProjectReposOutputBody{}); err != nil {
237					t.Errorf("encode empty: %v", err)
238				}
239			})
240			_, err := resolveRepoRef(context.Background(), c, "nope", ulidProjectWidgets)
241			if err == nil || !strings.Contains(err.Error(), "no repo named") {
242				t.Errorf("resolveRepoRef unknown name: err = %v, want a \"no repo named\" error", err)
243			}
244		})
245	}
